import json
import time

import boto3

from observability_client import get_observability_client


def write_correlated_logs(payload, correlation_id, config=None):
    config = config or {}
    client = get_observability_client(config)
    response = client.put_log_events(
        logGroupName=config["log_group"],
        logStreamName=config["log_stream"],
        logEvents=[{
            "timestamp": int(payload.get("timestamp_ms", time.time() * 1000)),
            "message": json.dumps(payload["event"]),
            "correlation_id": correlation_id,
        }],
    )
    if response.get("rejectedLogEventsInfo") or response.get("rejectedEntityInfo"):
        raise RuntimeError("The logging service rejected the event")
    return {"submitted": True}

import boto3


def get_observability_client(config=None):
    config = config or {}
    return boto3.client("logs", region_name=config.get("region"))

from typing import Any, Dict


def normalize_log_event(event: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "timestamp_ms": event.get("timestamp", None),
        "message": event.get("message", None),
        "correlation_id": event.get("correlation_id", None),
    }

import re


def check_log_text_safety(log_text: str) -> bool:
    unsafe_patterns = [
        r"password",
        r"secret",
        r"token",
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, log_text, re.IGNORECASE):
            return False
    return True
